{"code": "const out = await page.evaluate(() => {
  function walk(rules, path, out) {
    for (let i = 0; i < rules.length; i++) {
      const r = rules[i];
      if (r.selectorText && (r.selectorText.includes('-without-background') || (r.selectorText.includes('-on-color') && !r.selectorText.includes('--')))) {
        out.push({ path, idx: i, selector: r.selectorText });
      }
      if (r.cssRules) walk(r.cssRules, path + '>' + i, out);
    }
  }
  const out = [];
  let sheetIdx = 0;
  for (const sheet of document.styleSheets) {
    let cssRules;
    try { cssRules = sheet.cssRules; } catch(e) { sheetIdx++; continue; }
    if (!cssRules) { sheetIdx++; continue; }
    walk(cssRules, 'sheet'+sheetIdx, out);
    sheetIdx++;
  }
  return out;
});
return out;", "pageId": "6fd998d9-8a3a-441f-91fe-cddf4ac5c562"}

